// src/peer/records.mjs
//
// Accepted-result records for the agent-bridge controller.
//
// When the controller reviews and accepts a root task, exactly ONE Markdown record is
// written into the project (kept forever) and one JSON Lines event is appended to an
// index that lives outside the project. Raw harness sessions are deleted later by a
// sweeper; the record is the durable substitute, so it is generated by code from the
// stored data and NEVER summarised by a model: the original objective, acceptance
// items, peer prompts, answers and result texts are embedded verbatim. Every untrusted
// text placed in a fence gets a fence longer than the longest backtick run inside it,
// so no stored text can break out of its block. renderRecord is deterministic: the same
// input always renders the same bytes (the caller passes closedAt/eligibleAt in).
//
// The module is pure with respect to process state: every filesystem touch goes through
// an injectable seam, and no Date.now() is read.

import { createHash, randomBytes } from 'node:crypto';
import { appendFile, mkdir, readFile, rename, stat, writeFile } from 'node:fs/promises';
import path from 'node:path';

import { PeerPolicyError } from './chain.mjs';

/** The exclusion pattern keeps generated records out of the project's own diffs. */
export const DEFAULT_EXCLUDE_PATTERN = '/.agent-bridge/';
/** Accepted records are eligible for session cleanup after this many days. */
export const DEFAULT_RETAIN_DAYS = 3;
/** Failed/disputed/unresolved records are kept longer before cleanup. */
export const DEFAULT_DISPUTED_RETAIN_DAYS = 30;
/** Default record directory, relative to the project root. */
export const DEFAULT_RECORD_DIR = '.agent-bridge/records';
export const INDEX_FILE = 'records-index.jsonl';
export const RECORD_MISSING = '（无）';

const DAY_MS = 24 * 60 * 60 * 1000;
const MAX_SLUG_CHARS = 40;
const OUTCOMES_RETAINED_LONGER = Object.freeze(['failed', 'disputed', 'unresolved']);
const OUTCOMES = Object.freeze(['accepted', ...OUTCOMES_RETAINED_LONGER]);
const SESSION_STATES = Object.freeze(['archived', 'deleted', 'skipped', 'failed']);
const INDEX_KINDS = Object.freeze(['record', 'session']);

function isObject(value) {
  return typeof value === 'object' && value !== null && !Array.isArray(value);
}

function sha256Hex(text) {
  return createHash('sha256').update(text, 'utf8').digest('hex');
}

function isNotFound(error) {
  return error?.code === 'ENOENT' || error?.code === 'ENOTDIR';
}

/**
 * True when `target` exists. Only "does not exist" is swallowed; permission and I/O
 * errors propagate so a wrong answer is never silently produced.
 */
async function entryExists(target, statImpl) {
  try {
    await statImpl(target);
    return true;
  } catch (error) {
    if (isNotFound(error)) return false;
    throw error;
  }
}

function requireAbsolutePath(value, field) {
  if (typeof value !== 'string' || value === '' || !path.isAbsolute(value)) {
    throw new PeerPolicyError('PEER_ARGS_INVALID', `${field} must be an absolute path`, { field });
  }
  return value;
}

function requireText(value, field) {
  if (typeof value !== 'string') {
    throw new PeerPolicyError('PEER_ARGS_INVALID', `${field} must be a string`, { field });
  }
  return value;
}

/**
 * Walk up from `dir` to the nearest ancestor (including `dir` itself) that holds an
 * entry named `.git` — a directory for a normal checkout, a file for a linked worktree
 * or a submodule. Returns `dir` unchanged when no ancestor has one, so a non-git
 * project still gets a well-defined root.
 *
 * @param {string} dir absolute starting directory
 * @param {{statImpl?: Function}} [options]
 * @returns {Promise<string>}
 */
export async function findProjectRoot(dir, { statImpl = stat, stat: statOverride = null } = {}) {
  const start = requireAbsolutePath(dir, 'dir');
  const statFn = statOverride ?? statImpl;
  if (typeof statFn !== 'function') {
    throw new PeerPolicyError('PEER_ARGS_INVALID', 'findProjectRoot needs a stat function', { field: 'statImpl' });
  }
  let current = start;
  for (;;) {
    if (await entryExists(path.join(current, '.git'), statFn)) return current;
    const parent = path.dirname(current);
    if (parent === current) return start;
    current = parent;
  }
}

/** Read `<root>/.git` when it is a file ("gitdir: <path>") and resolve the gitdir. */
async function resolveGitDir(root, { stat, readFile: readFileImpl }) {
  const dotGit = path.join(root, '.git');
  const text = await readFileImpl(dotGit, 'utf8');
  const line = String(text).split('\n').map((part) => part.trim()).find((part) => part.length > 0) ?? '';
  const match = /^gitdir:\s*(.+)$/i.exec(line);
  if (!match) {
    throw new PeerPolicyError('PEER_ARGS_INVALID', `${dotGit} is not a gitdir pointer`, { field: 'projectRoot' });
  }
  const declared = match[1].trim();
  const gitDir = path.isAbsolute(declared) ? path.normalize(declared) : path.resolve(root, declared);
  const commonFile = path.join(gitDir, 'commondir');
  if (await entryExists(commonFile, stat)) {
    const common = (await readFileImpl(commonFile, 'utf8')).trim();
    if (common !== '') {
      return path.isAbsolute(common) ? path.normalize(common) : path.resolve(gitDir, common);
    }
  }
  return gitDir;
}

/**
 * Make sure `pattern` is excluded through git's own exclude file. This is the
 * `.git/info/exclude` mechanism, which is local to the checkout and never touches the
 * project's tracked `.gitignore`:
 *   * `<root>/.git` directory          -> `<root>/.git/info/exclude`
 *   * `<root>/.git` file (worktree)    -> `<gitdir>/info/exclude`, or
 *                                         `<commondir>/info/exclude` when the gitdir
 *                                         declares a commondir (linked worktree)
 *   * no `.git` at all                 -> {excluded:false, reason:'not-a-git-repository'}
 *
 * Existing content and its line endings are preserved byte for byte; the pattern is
 * appended on its own line only when no existing line equals it after trimming.
 *
 * @returns {Promise<{excluded: boolean, reason: string, file: string|null}>}
 */
export async function ensureGitExclude(projectRoot, {
  pattern = DEFAULT_EXCLUDE_PATTERN,
  stat: statImpl = stat,
  statImpl: statOverride = null,
  readFile: readFileImpl = readFile,
  mkdir: mkdirImpl = mkdir,
  appendFile: appendFileImpl = appendFile,
} = {}) {
  const root = requireAbsolutePath(projectRoot, 'projectRoot');
  const wanted = requireText(pattern, 'pattern');
  const statFn = statOverride ?? statImpl;
  const dotGit = path.join(root, '.git');

  if (!(await entryExists(dotGit, statFn))) {
    return { excluded: false, reason: 'not-a-git-repository', file: null };
  }
  const gitDir = (await statFn(dotGit)).isDirectory()
    ? dotGit
    : await resolveGitDir(root, { stat: statFn, readFile: readFileImpl });

  const infoDir = path.join(gitDir, 'info');
  const file = path.join(infoDir, 'exclude');
  await mkdirImpl(infoDir, { recursive: true });

  let existing = '';
  try {
    existing = await readFileImpl(file, 'utf8');
  } catch (error) {
    if (!isNotFound(error)) throw error;
    existing = '';
  }
  const present = existing.split('\n').some((line) => line.trim() === wanted);
  if (present) return { excluded: true, reason: 'present', file };

  // Append ONLY the new line. The seam is an append, so re-sending the bytes that are
  // already in the file would duplicate them. When the file does not end with a newline,
  // its own line ending (CRLF or LF) is written before the pattern's own line so the
  // existing content and its line endings stay untouched.
  let separator = '';
  if (existing !== '' && !existing.endsWith('\n')) {
    separator = existing.includes('\r\n') ? '\r\n' : '\n';
  }
  await appendFileImpl(file, `${separator}${wanted}\n`, 'utf8');
  return { excluded: true, reason: 'added', file };
}

function pad2(value) {
  return String(value).padStart(2, '0');
}

/** Local-time `YYYYMMDD-HHmm` for a millisecond timestamp. */
function localStamp(createdAt) {
  const date = new Date(createdAt);
  return `${date.getFullYear()}${pad2(date.getMonth() + 1)}${pad2(date.getDate())}-${pad2(date.getHours())}${pad2(date.getMinutes())}`;
}

/** Lowercase, non [a-z0-9] runs to '-', trimmed, capped at 40 chars, or 'record'. */
function slugify(title) {
  const slug = String(title ?? '')
    .toLowerCase()
    .replace(/[^a-z0-9]+/g, '-')
    .replace(/^-+|-+$/g, '')
    .slice(0, MAX_SLUG_CHARS);
  return slug === '' ? 'record' : slug;
}

/**
 * `YYYYMMDD-HHmm-<slug>-<hash6>.md` in LOCAL time. `hash6` ties the name to the exact
 * root task and creation instant, so two records of the same task cannot collide.
 */
export function recordFileName({ createdAt, title, rootTask } = {}) {
  if (typeof createdAt !== 'number' || !Number.isFinite(createdAt)) {
    throw new PeerPolicyError('PEER_ARGS_INVALID', 'createdAt must be a finite epoch-millisecond number', { field: 'createdAt' });
  }
  const task = requireText(rootTask, 'rootTask');
  const hash6 = sha256Hex(`${task}\n${createdAt}`).slice(0, 6);
  return `${localStamp(createdAt)}-${slugify(title)}-${hash6}.md`;
}

/**
 * When the raw sessions behind a record may be swept: null means "keep forever".
 * Accepted work is retained briefly; failed, disputed and unresolved work is retained
 * long enough to be re-examined.
 */
export function computeEligibleAt({ closedAt, outcome, keep = false, retainDays = DEFAULT_RETAIN_DAYS, disputedRetainDays = DEFAULT_DISPUTED_RETAIN_DAYS } = {}) {
  if (keep) return null;
  if (typeof closedAt !== 'number' || !Number.isFinite(closedAt)) {
    throw new PeerPolicyError('PEER_ARGS_INVALID', 'closedAt must be a finite epoch-millisecond number', { field: 'closedAt' });
  }
  if (outcome === 'accepted') return closedAt + retainDays * DAY_MS;
  if (OUTCOMES_RETAINED_LONGER.includes(outcome)) return closedAt + disputedRetainDays * DAY_MS;
  throw new PeerPolicyError('PEER_ARGS_INVALID', `unknown outcome "${String(outcome)}"; expected one of ${OUTCOMES.join(', ')}`, { field: 'outcome' });
}

function text(value) {
  return typeof value === 'string' ? value : '';
}

function inline(value) {
  return text(value) === '' ? RECORD_MISSING : text(value);
}

/**
 * A fence for untrusted text that is longer than the longest backtick run inside it,
 * with a minimum of three backticks. Nothing in the text can close the fence early.
 */
export function fenceSafe(value) {
  const body = text(value);
  let longest = 0;
  for (const run of body.match(/`+/g) ?? []) longest = Math.max(longest, run.length);
  const ticks = '`'.repeat(Math.max(3, longest + 1));
  const tail = body.endsWith('\n') || body === '' ? '' : '\n';
  return `${ticks}\n${body}${tail}${ticks}`;
}

/** Escape a Markdown table cell: pipes and newlines must not split the row. */
function cell(value) {
  const body = text(value) === '' ? RECORD_MISSING : text(value);
  return body.replace(/\|/g, '\\|').replace(/\r\n|\r|\n/g, '<br>');
}

function isoOrText(value) {
  return typeof value === 'number' && Number.isFinite(value) ? new Date(value).toISOString() : inline(value);
}

function sessionEntry(harness, sessionId, source) {
  return { harness: inline(harness), id: text(sessionId), source: text(source) };
}

function sessionsOf({ bridgeTasks, peerJobs }) {
  const sessions = [];
  for (const task of bridgeTasks) {
    if (!isObject(task)) continue;
    // A bridge task is a DSH task: its taskId and sessionId live inside `dossier`
    // (the packet's dossier is the input shape), not on the outer task wrapper.
    const dossier = isObject(task.dossier) ? task.dossier : {};
    if (typeof dossier.sessionId === 'string' && dossier.sessionId !== '') {
      sessions.push(sessionEntry(dossier.harness ?? 'dsh', dossier.sessionId, dossier.taskId));
    }
  }
  for (const entry of peerJobs) {
    if (!isObject(entry)) continue;
    const job = isObject(entry.job) ? entry.job : {};
    if (typeof job.sessionId === 'string' && job.sessionId !== '') {
      sessions.push(sessionEntry(job.target, job.sessionId, job.jobId));
    }
  }
  return sessions;
}

function renderRecordHeading(input) {
  const sessions = sessionsOf(input);
  const front = {
    recordId: input.recordId ?? null,
    rootTask: input.rootTask ?? null,
    title: input.title ?? null,
    projectRoot: input.projectRoot ?? null,
    controller: input.controller ?? null,
    chain: input.chain ?? null,
    closedAt: isoOrText(input.closedAt),
    outcome: input.outcome ?? null,
    keep: input.keep === true,
    eligibleAt: typeof input.eligibleAt === 'number' && Number.isFinite(input.eligibleAt) ? new Date(input.eligibleAt).toISOString() : null,
    bridgeTaskIds: input.bridgeTasks.filter(isObject).map((task) => (isObject(task.dossier) ? task.dossier.taskId ?? null : null)),
    peerJobIds: input.peerJobs.filter(isObject).map((entry) => (isObject(entry.job) ? entry.job.jobId ?? null : null)),
    sessions,
  };
  return {
    heading: `# ${String(input.title ?? '')}`,
    block: ['```json agent-bridge-record', JSON.stringify(front, null, 2), '```'].join('\n'),
    sessions,
  };
}

function renderConclusion(input) {
  const lines = [
    '## 结论',
    `- 结果: ${inline(input.outcome)}`,
    `- 保留: ${input.keep === true ? '是（永久保留会话）' : '否'}`,
    `- 会话可清理时间: ${input.eligibleAt === null || input.eligibleAt === undefined ? '永久保留' : new Date(input.eligibleAt).toISOString()}`,
    '',
    '结论正文:',
    '',
    text(input.conclusion),
  ];
  return lines.join('\n');
}

function renderFindings(findings) {
  const rows = [
    '## 交叉验证',
    '',
    '| 编号 | 提出方 | 结论 | 说明 | 证据 |',
    '| --- | --- | --- | --- | --- |',
  ];
  for (const finding of findings) {
    const item = isObject(finding) ? finding : {};
    const raisedBy = Array.isArray(item.raisedBy) ? item.raisedBy.map((value) => text(value)).join('、') : text(item.raisedBy);
    rows.push(`| ${cell(item.id)} | ${cell(raisedBy)} | ${cell(item.verdict)} | ${cell(item.summary)} | ${cell(item.evidence)} |`);
  }
  return rows.join('\n');
}

function renderChecks(checks) {
  if (!Array.isArray(checks) || checks.length === 0) return RECORD_MISSING;
  const rows = ['| 命令 | 参数 | 退出码 | 通过 |', '| --- | --- | --- | --- |'];
  for (const check of checks) {
    const item = isObject(check) ? check : {};
    const args = Array.isArray(item.args) ? item.args.map((value) => String(value)).join(' ') : text(item.args);
    rows.push(`| ${cell(item.command)} | ${cell(args)} | ${cell(item.exitCode)} | ${item.ok === true ? '是' : item.ok === false ? '否' : RECORD_MISSING} |`);
  }
  return rows.join('\n');
}

function renderBridgeTask(task) {
  const dossier = isObject(task.dossier) ? task.dossier : {};
  const request = isObject(dossier.request) ? dossier.request : {};
  const model = isObject(dossier.effectiveModel) ? dossier.effectiveModel : {};
  const stats = isObject(dossier.stats) ? dossier.stats : {};
  const workspace = isObject(dossier.workspace) ? dossier.workspace : {};
  const review = isObject(dossier.review) ? dossier.review : {};
  const integration = isObject(dossier.integration) ? dossier.integration : {};
  const acknowledgement = isObject(dossier.acknowledgement) ? dossier.acknowledgement : {};
  const acceptance = Array.isArray(request.acceptance) ? request.acceptance : [];

  const lines = [
    `### ${inline(dossier.title)} (${inline(dossier.taskId)})`,
    '',
    `- 角色: ${inline(dossier.role)}`,
    `- 状态: ${inline(dossier.status)}`,
    `- 控制器: ${inline(dossier.controller)}`,
    `- 模型: ${inline(model.provider)}/${inline(model.model)}${text(model.reasoningEffort) === '' ? '' : ` (reasoningEffort=${model.reasoningEffort})`}`,
    `- 工具调用: ${stats.toolCalls === undefined || stats.toolCalls === null ? RECORD_MISSING : String(stats.toolCalls)}`,
    '',
    '目标:',
    '',
    text(request.objective) === '' ? RECORD_MISSING : text(request.objective),
    '',
    '验收标准:',
    '',
    acceptance.length === 0 ? RECORD_MISSING : acceptance.map((item) => `- ${text(item)}`).join('\n'),
    '',
    `- 工作目录: ${inline(request.cwd)}`,
    `- 分支: ${inline(workspace.branch)}`,
    `- 起始提交: ${inline(workspace.baseCommit)}`,
    `- 工作区: ${inline(workspace.path)}`,
    '',
    `#### 复核`,
    '',
    `- 通过: ${review.passed === true ? '是' : review.passed === false ? '否' : RECORD_MISSING}`,
    `- 复核提交: ${inline(review.head)}`,
    '',
    '检查:',
    '',
    renderChecks(review.checks),
    '',
    '#### 集成',
    '',
    `- 已合并: ${integration.merged === true ? '是' : integration.merged === false ? '否' : RECORD_MISSING}`,
    `- 已接受: ${integration.accepted === true ? '是' : integration.accepted === false ? '否' : RECORD_MISSING}`,
    `- 目标合并前: ${inline(integration.targetHeadBefore)}`,
    `- 目标合并后: ${inline(integration.targetHeadAfter)}`,
    '',
    '#### 结果确认',
    '',
    `- 已接受: ${acknowledgement.accepted === true ? '是' : acknowledgement.accepted === false ? '否' : RECORD_MISSING}`,
    `- 工件状态: ${inline(acknowledgement.artifactState)}`,
    '',
    '#### 结果全文',
    '',
    task.resultText === null || task.resultText === undefined ? RECORD_MISSING : fenceSafe(task.resultText),
  ];
  if (text(dossier.sessionId) !== '') lines.push('', `- 会话: ${dossier.sessionId}`);
  return lines.join('\n');
}

/**
 * The model/effort line of one peer job: what was PASSED to the peer CLI and where it
 * came from (call | config | cli-default). A job recorded before these fields existed
 * has neither, and is rendered with the usual missing-value marker.
 */
function renderPeerModel(job) {
  const known = job.model !== undefined || job.modelSource !== undefined
    || job.reasoningEffort !== undefined || job.effortSource !== undefined;
  if (!known) return `- 模型: ${RECORD_MISSING} · 思考强度: ${RECORD_MISSING}`;
  const source = (value) => (typeof value === 'string' && value !== '' ? value : 'cli-default');
  const model = job.model === undefined || job.model === null ? 'CLI 默认' : inline(job.model);
  const effort = job.reasoningEffort === undefined || job.reasoningEffort === null ? 'CLI 默认' : inline(job.reasoningEffort);
  return `- 模型: ${model}（${source(job.modelSource)}） · 思考强度: ${effort}（${source(job.effortSource)}）`;
}

function renderPeerJob(entry) {
  const job = isObject(entry.job) ? entry.job : {};
  const chain = Array.isArray(job.chain) ? job.chain.map((value) => text(value)).join(' > ') : text(job.chain);
  const errors = Array.isArray(job.errors) ? job.errors : [];
  const usage = isObject(job.usage) ? JSON.stringify(job.usage) : job.usage === undefined || job.usage === null ? '' : String(job.usage);
  const lines = [
    `### ${inline(job.target)} · ${inline(job.mode)} (${inline(job.jobId)})`,
    '',
    `- 状态: ${inline(job.status)}`,
    `- 链: ${chain === '' ? RECORD_MISSING : chain}`,
    `- 会话: ${inline(job.sessionId)}`,
    renderPeerModel(job),
    `- 开始: ${isoOrText(job.startedAt)}`,
    `- 结束: ${isoOrText(job.endedAt)}`,
    `- 用量: ${usage === '' ? RECORD_MISSING : usage}`,
    `- 成本(USD): ${job.costUsd === undefined || job.costUsd === null ? RECORD_MISSING : String(job.costUsd)}`,
    `- 错误: ${errors.length === 0 ? RECORD_MISSING : errors.map((value) => text(value)).join('；')}`,
    '',
    '#### 请求',
    '',
    entry.promptText === null || entry.promptText === undefined ? RECORD_MISSING : fenceSafe(entry.promptText),
    '',
    '#### 答复全文',
    '',
    entry.finalMessage === null || entry.finalMessage === undefined ? RECORD_MISSING : fenceSafe(entry.finalMessage),
  ];
  return lines.join('\n');
}

function renderCleanup(input, sessions) {
  const lines = ['## 会话清理', ''];
  if (sessions.length === 0) {
    lines.push(RECORD_MISSING);
  } else {
    for (const session of sessions) {
      lines.push(`- 运行器=${session.harness} 会话=${session.id} 来源=${session.source}`);
    }
  }
  lines.push('', `- 可清理时间: ${input.keep === true || input.eligibleAt === null || input.eligibleAt === undefined ? '永久保留' : new Date(input.eligibleAt).toISOString()}`);
  return lines.join('\n');
}

/**
 * Render the ONE durable Markdown record for an accepted root task. Pure and
 * deterministic: no clock, no I/O, no model. Every untrusted text is embedded verbatim
 * inside a fence that its own content cannot close.
 *
 * @param {object} input see the module contract (record header fields, findings,
 *   bridgeTasks, peerJobs).
 * @returns {string}
 */
export function renderRecord(input = {}) {
  if (!isObject(input)) {
    throw new PeerPolicyError('PEER_ARGS_INVALID', 'renderRecord needs an input object', { field: 'input' });
  }
  const normalized = {
    ...input,
    chain: typeof input.chain === 'string' ? input.chain : Array.isArray(input.chain) ? input.chain.join(' > ') : (input.chain ?? ''),
    findings: Array.isArray(input.findings) ? input.findings.filter(isObject) : [],
    bridgeTasks: Array.isArray(input.bridgeTasks) ? input.bridgeTasks.filter(isObject) : [],
    peerJobs: Array.isArray(input.peerJobs) ? input.peerJobs.filter(isObject) : [],
  };
  normalized.keep = normalized.keep === true;

  const { heading, block, sessions } = renderRecordHeading(normalized);
  const parts = [heading, '', block, '', renderConclusion(normalized)];
  if (normalized.findings.length > 0) parts.push('', renderFindings(normalized.findings));
  parts.push('', '## DSH 任务');
  if (normalized.bridgeTasks.length === 0) parts.push('', RECORD_MISSING);
  for (const task of normalized.bridgeTasks) parts.push('', renderBridgeTask(task));
  parts.push('', '## Peer 调用');
  if (normalized.peerJobs.length === 0) parts.push('', RECORD_MISSING);
  for (const entry of normalized.peerJobs) parts.push('', renderPeerJob(entry));
  parts.push('', renderCleanup(normalized, sessions));
  return `${parts.join('\n')}\n`;
}

function requireWritableRoot(projectRoot) {
  return requireAbsolutePath(projectRoot, 'projectRoot');
}

function requireRelativeDir(dirName) {
  if (typeof dirName !== 'string' || dirName === '' || path.isAbsolute(dirName)) {
    throw new PeerPolicyError('PEER_ARGS_INVALID', 'dirName must be a nonempty relative path', { field: 'dirName' });
  }
  return dirName;
}

function requireFileName(fileName) {
  if (typeof fileName !== 'string' || fileName === '' || path.isAbsolute(fileName)) {
    throw new PeerPolicyError('PEER_ARGS_INVALID', 'fileName must be a nonempty relative file name', { field: 'fileName' });
  }
  const normalized = path.normalize(fileName);
  if (normalized.startsWith('..') || path.dirname(normalized) !== '.') {
    throw new PeerPolicyError('PEER_ARGS_INVALID', 'fileName must not escape the record directory', { field: 'fileName' });
  }
  return normalized;
}

/**
 * Write one record under `<projectRoot>/<dirName>/<fileName>` without ever overwriting
 * an existing record: the bytes land in a temp file in the same directory and are then
 * renamed into place. `sha256` is the hash of the written UTF-8 bytes, not of the path.
 *
 * @returns {Promise<{path: string, sha256: string, bytes: number}>}
 */
export async function writeRecord({
  projectRoot,
  dirName = DEFAULT_RECORD_DIR,
  fileName,
  content,
  stat: statImpl = stat,
  statImpl: statOverride = null,
  mkdir: mkdirImpl = mkdir,
  writeFile: writeFileImpl = writeFile,
  rename: renameImpl = rename,
} = {}) {
  const root = requireWritableRoot(projectRoot);
  const dir = requireRelativeDir(dirName);
  const name = requireFileName(fileName);
  if (typeof content !== 'string') {
    throw new PeerPolicyError('PEER_ARGS_INVALID', 'content must be a string', { field: 'content' });
  }
  const statFn = statOverride ?? statImpl;
  const file = path.join(root, dir, name);
  await mkdirImpl(path.dirname(file), { recursive: true });
  if (await entryExists(file, statFn)) {
    throw new PeerPolicyError('PEER_RECORD_EXISTS', `record already exists: ${name}`, { field: 'fileName', path: file });
  }
  const tmp = `${file}.${process.pid}.${randomBytes(3).toString('hex')}.tmp`;
  await writeFileImpl(tmp, content, 'utf8');
  try {
    await renameImpl(tmp, file);
  } catch (error) {
    if (!(await entryExists(file, statFn))) throw error;
    throw new PeerPolicyError('PEER_RECORD_EXISTS', `record already exists: ${name}`, { field: 'fileName', path: file });
  }
  return { path: file, sha256: sha256Hex(content), bytes: Buffer.byteLength(content, 'utf8') };
}

function indexFileOf(stateDir) {
  return path.join(stateDir, INDEX_FILE);
}

function requireEventKind(event) {
  if (!isObject(event) || typeof event.kind !== 'string' || !INDEX_KINDS.includes(event.kind)) {
    throw new PeerPolicyError('PEER_ARGS_INVALID', `index events must have kind 'record' or 'session'`, { field: 'event.kind' });
  }
  return event.kind;
}

function recordStateFromEvent(event) {
  const sessions = new Map();
  for (const session of Array.isArray(event.sessions) ? event.sessions : []) {
    if (!isObject(session)) continue;
    sessions.set(`${text(session.harness)}\u0000${text(session.id)}`, {
      harness: session.harness ?? null,
      id: session.id ?? null,
      source: session.source ?? null,
      state: 'pending',
      note: null,
      at: null,
    });
  }
  return {
    recordId: event.recordId ?? null,
    rootTask: event.rootTask ?? null,
    title: event.title ?? null,
    projectRoot: event.projectRoot ?? null,
    path: event.path ?? null,
    sha256: event.sha256 ?? null,
    outcome: event.outcome ?? null,
    keep: event.keep === true,
    closedAt: event.closedAt ?? null,
    eligibleAt: event.eligibleAt ?? null,
    sessions: sessions,
  };
}

/**
 * An ordered fold of the index. Carries `skipped`, the number of lines that count as
 * skipped: lines that are not usable index events (invalid JSON, a JSON value that is
 * not an object, or an unrecognized `kind`) plus session events naming a recordId the
 * index does not know. It is not a record id.
 */
class RecordIndex extends Map {
  constructor() {
    super();
    this.skipped = 0;
  }
}

/**
 * Append ONE JSON Lines event to `<stateDir>/records-index.jsonl`. A missing directory
 * is created; existing lines are never rewritten. The line is built before anything is
 * touched, so an invalid event appends nothing.
 *
 * @returns {Promise<object>} the appended event (with `at`)
 */
export async function appendIndexEvent(stateDir, event, {
  now = () => Date.now(),
  mkdir: mkdirImpl = mkdir,
  appendFile: appendFileImpl = appendFile,
} = {}) {
  if (typeof stateDir !== 'string' || stateDir === '' || !path.isAbsolute(stateDir)) {
    throw new PeerPolicyError('PEER_ARGS_INVALID', 'stateDir must be an absolute path', { field: 'stateDir' });
  }
  requireEventKind(event);
  const entry = { at: now(), ...event };
  const line = `${JSON.stringify(entry)}\n`;
  await mkdirImpl(stateDir, { recursive: true });
  await appendFileImpl(indexFileOf(stateDir), line, 'utf8');
  return entry;
}

/**
 * Fold the index in file order. A `record` event creates the entry and marks every one
 * of its sessions `pending`; a `session` event updates that one session's state, note
 * and time.
 *
 * `map.skipped` counts exactly two categories, as the specification enumerates them:
 *   * lines that are not usable index events — invalid JSON, a JSON value that is not an
 *     object, or an event whose `kind` is neither `record` nor `session`; and
 *   * session events naming a recordId the index does not know.
 * A blank line (including the trailing newline of a well-formed file) is not an event
 * line and is not counted. A recognized event that simply cannot be applied — a `record`
 * event with no `recordId`, or a session event whose record does not list that session —
 * is skipped without incrementing `skipped`.
 *
 * A missing index file is an empty index, not an error.
 *
 * @returns {Promise<Map<string, object>>}
 */
export async function readIndex(stateDir, { readFile: readFileImpl = readFile } = {}) {
  if (typeof stateDir !== 'string' || stateDir === '' || !path.isAbsolute(stateDir)) {
    throw new PeerPolicyError('PEER_ARGS_INVALID', 'stateDir must be an absolute path', { field: 'stateDir' });
  }
  const index = new RecordIndex();
  let raw = '';
  try {
    raw = await readFileImpl(indexFileOf(stateDir), 'utf8');
  } catch (error) {
    if (isNotFound(error)) return index;
    throw error;
  }
  for (const line of raw.split('\n')) {
    const trimmed = line.trim();
    if (trimmed === '') continue;
    let event;
    try {
      event = JSON.parse(trimmed);
    } catch {
      index.skipped += 1;
      continue;
    }
    if (!isObject(event) || (event.kind !== 'record' && event.kind !== 'session')) {
      index.skipped += 1;
      continue;
    }
    if (event.kind === 'record') {
      const id = String(event.recordId ?? '');
      // A record event with no recordId cannot create a state. The specification counts
      // only unknown recordIds in SESSION events and unparsable lines, so this line is
      // skipped without incrementing `skipped`.
      if (id === '') continue;
      index.set(id, recordStateFromEvent(event));
      continue;
    }
    const record = index.get(String(event.recordId ?? ''));
    if (!record) {
      index.skipped += 1;
      continue;
    }
    const key = `${text(event.harness)}\u0000${text(event.id)}`;
    // A known record whose session list does not name this session (and a session event
    // whose recordId is known) is not one of the counted categories: skip it silently.
    if (!record.sessions.has(key)) continue;
    const session = record.sessions.get(key);
    session.state = SESSION_STATES.includes(event.state) ? event.state : session.state;
    session.note = event.note ?? null;
    session.at = 'at' in event ? event.at ?? null : null;
  }
  return index;
}

/** Re-exported so a caller can assert the exported surface without guessing names. */
export const RECORD_EXPORTS = Object.freeze([
  'findProjectRoot',
  'ensureGitExclude',
  'recordFileName',
  'computeEligibleAt',
  'renderRecord',
  'writeRecord',
  'appendIndexEvent',
  'readIndex',
]);
